def prior(*keys, summary=True, legacy=(), sha=SHA):
    bodies = []
    if summary:
        bodies.append(
            {
                "body": HEADER
                + "Summary"
                + FOOTER.replace("{count}", "0").replace(SHA, sha)
            }
        )
    for key in keys:
        bodies.append(
            {
                "body": (
                    "Corroborating finding \u2014 member\n" if key in legacy else ""
                )
                + (
                    '\n\n<!-- code-gauntlet-finding-key: {"sha":"'
                    + sha
                    + '","key":"'
                    + key
                    + '"} -->'
                )
            }
        )
    return JsonFetch(bodies, None)


def review(platform="github", findings=(), **values):
    return {
        "platform": platform,
        "owner": "o",
        "repo": "r",
        "pr_number": 5,
        "sha": SHA,
        "review_body": "Summary",
        "findings": list(findings),
        **values,
    }


@dataclass(frozen=True, slots=True)
class PostingRun:
    code: int
    out: str
    err: str
    payload: dict | None
    raw: bytes | None
    requests: tuple[PostRequest, ...]
    fake: FakeForge
    head_calls: tuple[tuple[str, ...], ...]


def invoke_posting(
    directory,
    monkeypatch,
    capsys,
    factory,
    data,
    *,
    diff="",
    diff_status=0,
    diff_error="",
    refs=None,
    entries=None,
    submissions=None,
    availability=None,
    dry_run=True,
    arguments=(),
    head="deadbeefcafe\n",
    head_status=0,
):
    path = directory / "findings.json"
    path.write_text(json.dumps(data, ensure_ascii=False), encoding="utf-8")
    artifact = Path(os.path.abspath(path)).parent / "post-review-payload.json"
    artifact.unlink(missing_ok=True)
    platform = data.get("platform", "github") if isinstance(data, dict) else "github"
    options = {
        "diffs": [(diff, diff_error, diff_status)],
        "entries": [entries] if entries is not None else None,
        "submissions": submissions,
        "availability": availability,
    }
    fake = (
        FakeGitLab(
            refs=[
                refs
                if refs is not None
                else JsonFetch(
                    [
                        {
                            "base_commit_sha": "base1",
                            "head_commit_sha": "head1",
                            "start_commit_sha": "start1",
                        }
                    ],
                    None,
                )
            ],
            **options,
        )
        if platform == "gitlab"
        else FakeForge(**options)
    )
    factory.configure(fake)
    head_calls = []

    def run(command, **kwargs):
        assert command == ["git", "rev-parse", "HEAD"]
        assert kwargs == {"cwd": None, "timeout": None, "errors": "strict"}
        head_calls.append(tuple(command))
        return proc.CompletedProcess(command, head_status, head, "")

    monkeypatch.setattr(proc, "run", run)
    monkeypatch.delenv("CODE_GAUNTLET_POST_MODE", raising=False)
    capsys.readouterr()
    code = post.CLI.invoke([str(path), *arguments, *(["--dry-run"] if dry_run else [])])
    captured = capsys.readouterr()
    raw = artifact.read_bytes() if artifact.exists() else None
    return PostingRun(
        code,
        captured.out,
        captured.err,
        json.loads(raw) if raw is not None else None,
        raw,
        tuple(call.request for call in fake.calls if call.request is not None),
        fake,
        tuple(head_calls),
    )
